type RankBlock struct {
	Atk *int `json:"atk,omitempty"`
	Def *int `json:"def,omitempty"`
	Spa *int `json:"spa,omitempty"`
	Spd *int `json:"spd,omitempty"`
	Spe *int `json:"spe,omitempty"`
}

